'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const Module = require('node:module');
const { once } = require('node:events');
const root = '/home/jyarwood/workspace/pi-dish-r4';
const dir = __dirname;
const req = Module.createRequire(path.join(root, 'package.json'));
const home = path.join(dir, 'home');
fs.mkdirSync(home, { recursive: true });
const env = req('./test/test-env').sanitizeTestEnv({ PATH: process.env.PATH, LANG: 'C.UTF-8', HOME: home, SHELL: '/bin/sh', TMPDIR: dir, TMUX_TMPDIR: path.join(dir, 'tmux') });
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env, { GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null', GIT_AUTHOR_NAME: 'R4', GIT_AUTHOR_EMAIL: 'r4@test', GIT_COMMITTER_NAME: 'R4', GIT_COMMITTER_EMAIL: 'r4@test' });
fs.mkdirSync(process.env.TMUX_TMPDIR, { recursive: true });
const workspace = path.join(home, 'workspace');
const repo = path.join(workspace, 'repo');
fs.mkdirSync(repo, { recursive: true });
function git(...args) { return cp.execFileSync('git', args, { cwd: repo, encoding: 'utf8' }); }
git('init', '-q', '-b', 'main');
for (let i = 0; i < 7; i++) fs.writeFileSync(path.join(repo, `file-${i}.txt`), `old ${i}\n`);
git('add', '-A'); git('commit', '-q', '-m', 'fixture');
for (let i = 0; i < 7; i++) fs.appendFileSync(path.join(repo, `file-${i}.txt`), `new ${i}\n`);
const markdown = '# R4 inert file\n\nA **rendered** finding.\n\n<script>globalThis.r4Executed = true</script>\n\n[unsafe](javascript:alert(1))\n';
fs.writeFileSync(path.join(workspace, 'view.md'), markdown);
fs.writeFileSync(path.join(workspace, 'raw.html'), '<script>globalThis.r4Executed=true</script>');
fs.writeFileSync(path.join(workspace, 'raw.svg'), '<svg xmlns="http://www.w3.org/2000/svg"><script>globalThis.r4Executed=true</script></svg>');
fs.writeFileSync(path.join(workspace, 'binary.bin'), Buffer.from([65, 0, 66]));
fs.writeFileSync(path.join(workspace, 'large.txt'), 'a'.repeat(512001));
fs.writeFileSync(path.join(workspace, 'large.png'), Buffer.alloc(8 * 1024 * 1024 + 1));
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==', 'base64');
fs.writeFileSync(path.join(workspace, 'small.png'), png);
fs.writeFileSync(path.join(home, 'secret.txt'), 'not reachable');
const sessions = path.join(home, '.pi/agent/sessions/fixture');
fs.mkdirSync(sessions, { recursive: true });
const id = 'r4-runtime-fixture';
fs.writeFileSync(path.join(sessions, id + '.jsonl'), JSON.stringify({ type: 'session', cwd: workspace, timestamp: new Date().toISOString() }) + '\n');
const results = { runtime: process.version, platform: process.platform, isolation: 'Allowlisted sanitizeTestEnv, temporary HOME/tmux/git, loopback ephemeral servers; no live sessions/provider credentials', proofs: [] };
function baseline(name, overrides = {}) {
  const filename = path.join(root, 'lib', '__r4_baseline_' + name + '.js');
  const mod = new Module(filename, module);
  mod.filename = filename; mod.paths = Module._nodeModulePaths(path.dirname(filename));
  const original = mod.require.bind(mod);
  mod.require = value => Object.hasOwn(overrides, value) ? overrides[value] : original(value);
  mod._compile(fs.readFileSync(path.join(dir, 'baseline-' + name + '.js'), 'utf8'), filename);
  return mod.exports;
}
async function main() {
  const server = req('./server');
  if (!server.listening) await once(server, 'listening');
  const base = `http://127.0.0.1:${server.address().port}`;
  const get = async route => { const res = await fetch(base + route); return { status: res.status, headers: Object.fromEntries(res.headers), body: await res.json() }; };
  const file = name => `/api/sessions/${id}/file?path=${encodeURIComponent(name)}`;
  assert.equal((await get(file('view.md:2'))).body.line, 2);
  for (const name of ['raw.html', 'raw.svg']) {
    const preview = await get(file(name)); assert.equal(preview.status, 200);
    const response = await fetch(base + `/api/sessions/${id}/file/content?path=${name}`);
    assert.equal(response.status, 200); assert.match(response.headers.get('content-type'), /^text\/plain/);
    assert.equal(response.headers.get('x-content-type-options'), 'nosniff');
    assert.equal(response.headers.get('cache-control'), 'private, no-cache');
    assert.equal(await response.text(), fs.readFileSync(path.join(workspace, name), 'utf8'));
  }
  const image = await get(file('small.png')); assert.equal(image.body.image.data, undefined);
  assert.deepEqual(Buffer.from(await (await fetch(base + image.body.image.url)).arrayBuffer()), png);
  const large = await get(file('large.txt')); assert.equal(large.body.truncated, true); assert.equal(large.body.content.length, 512000);
  for (const [name, status] of [['', 400], ['x'.repeat(1025), 400], ['binary.bin', 415], ['large.png', 413], ['../secret.txt', 404], ['missing.txt', 404]]) {
    const preview = await get(file(name));
    const raw = await get(`/api/sessions/${id}/file/content?path=${encodeURIComponent(name)}`);
    assert.equal(preview.status, status); assert.equal(raw.status, status); assert.deepEqual(raw.body, preview.body);
  }
  results.proofs.push('Actual server preview/raw: line, capped text, metadata-only image bytes, inert HTML/SVG, identical400/404/413/415 errors');
  const summary = await get(`/api/sessions/${id}/diff`); assert.equal(summary.status, 200);
  assert.ok(summary.body.repos[0].files.every(f => f.patchDeferred && f.patch === undefined));
  const patchRoute = name => `/api/sessions/${id}/diff/patch?${new URLSearchParams({repo: 'repo', path: name, snapshot: summary.body.snapshotId})}`;
  assert.equal((await get(patchRoute('../view.md'))).status, 404);
  assert.match((await get(patchRoute('file-3.txt'))).body.patch, /\+new 3/);
  const originalExec = cp.execFile;
  let release;
  let notify;
  const ready = new Promise(resolve => { notify = resolve; });
  cp.execFile = function(command, args, options, callback) {
    return originalExec.call(this, command, args, options, (error, stdout, stderr) => {
      if (options.cwd === repo && args.includes('diff') && args.includes('--no-color')) {
        release = () => callback(error, stdout, stderr); notify();
      } else callback(error, stdout, stderr);
    });
  };
  const pending = get(patchRoute('file-3.txt'));
  await Promise.race([ready, new Promise((_, reject) => { const timer = setTimeout(() => reject(new Error('patch delay not reached')), 5000); timer.unref(); })]);
  fs.appendFileSync(path.join(repo, 'file-3.txt'), 'changed while real patch callback held\n');
  cp.execFile = originalExec; release();
  const delayed = await pending; assert.equal(delayed.status, 409); assert.equal(delayed.body.stale, true); assert.equal(delayed.body.patch, undefined);
  assert.equal((await get(patchRoute('file-3.txt'))).status, 409);
  results.proofs.push('Real deferred git patch output held after pre-version check; changed file before callback release; actual HTTP409 stale without patch, then pre-generation stale409');
  const published = await fetch(base + '/api/pages', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: path.join(workspace, 'view.md'), sessionId: id, title: '<R4 & inert>', renderer: 'file' }) });
  assert.equal(published.status, 200); const page = await published.json();
  const rendered = await fetch(base + page.path); const html = await rendered.text();
  assert.match(rendered.headers.get('content-security-policy'), /default-src 'none'/);
  assert.match(html, /&lt;R4 &amp; inert&gt;/); assert.match(html, /&lt;script&gt;/); assert.match(html, /href="#"/);
  results.proofs.push('Actual publication standalone file renderer: title/raw HTML escaped, unsafe URL inert, restrictive CSP');

  // Compare accepted baseline and current HTTP handlers with exact same raw cwd values.
  const express = req('express'); const app = express();
  const old = baseline('file-handlers', { './git-diff': baseline('git-diff') });
  const current = req('./lib/file-handlers');
  let cwd;
  for (const [prefix, owner] of [['old', old], ['current', current]]) {
    const handlers = owner.createFileHandlers({ resolveSessionCwd() { return cwd; }, findSessionSource() { return null; } });
    for (const [route, handler] of [['files', 'searchSessionFiles'], ['file', 'filePreview'], ['file/content', 'fileContent'], ['diff', 'diffSummary'], ['diff/patch', 'diffPatch']]) app.get(`/${prefix}/:id/${route}`, handlers[handler]);
  }
  const compatibility = app.listen(0, '127.0.0.1'); await once(compatibility, 'listening');
  const compareBase = `http://127.0.0.1:${compatibility.address().port}`;
  let comparisons = 0;
  const values = [42, true, false, null, undefined, '', [], {}, workspace];
  for (const value of values) {
    cwd = value;
    for (const route of [`files?q=${encodeURIComponent(workspace + '/view')}`, 'files?q=./view', 'files?q=view', `file?path=${encodeURIComponent(path.join(workspace, 'view.md'))}`, 'file?path=view.md', 'file/content?path=view.md', 'diff', `diff/patch?repo=repo&path=file-3.txt&snapshot=${'a'.repeat(24)}`]) {
      const responses = [];
      for (const prefix of ['old', 'current']) {
        const response = await fetch(`${compareBase}/${prefix}/fixture/${route}`);
        const text = await response.text();
        let body;
        try { body = JSON.parse(text); } catch { body = text; }
        if (body && typeof body === 'object' && body.snapshotId) { assert.match(body.snapshotId, /^[a-f0-9]{24}$/); body.snapshotId = '<snapshot>'; }
        responses.push({ status: response.status, type: response.headers.get('content-type'), body });
      }
      assert.deepEqual(responses[1], responses[0], `cwd ${String(value)} route ${route}`); comparisons++;
    }
  }
  compatibility.close(); await once(compatibility, 'close');
  results.proofs.push(`${comparisons} accepted-baseline/current HTTP comparisons preserve raw unknown cwd response/errors and valid cwd`);
  const beforePage = baseline('file-page'); const afterPage = req('./lib/file-page');
  for (const title of [null, undefined, '', 42, true, {}, ['x'], '<&>"\'', { toString() { return '<custom>'; } }]) {
    const input = { token: 'token', root: '/view.md', title, file: { content: markdown, truncated: false, size: markdown.length, mtime: 1 } };
    assert.equal(afterPage.renderFilePage(input), beforePage.renderFilePage(input));
  }
  const { matchCommandPaths } = req('./lib/command-paths');
  const commands = [['cat /a/b ~/c/d', ['/a/b', '~/c/d']], ['X=/tmp/a <~/in >"/out/a"', ['/tmp/a', '~/in', '/out/a']], ['cat ~ ./relative ../up https://host/a /a:b /a\\ b', ['/a', '/a']], ['cat /tmp/a /tmp/a', ['/tmp/a', '/tmp/a']], ['cat /a.b/@x/%y/+z-1', ['/a.b/@x/%y/+z-1']]];
  for (const [command, expected] of commands) assert.deepEqual([...matchCommandPaths(command)].map(m => m[1]), expected);
  results.proofs.push('Nine native title/coercion standalone output comparisons and five matcher delimiter/partial/duplicate/relative examples');
  results.base = base; results.pageUrl = base + page.path;
  fs.writeFileSync(path.join(dir, 'result.json'), JSON.stringify(results, null, 2) + '\n');
  console.log('R4_SMOKE_READY ' + JSON.stringify(results));
  process.on('SIGTERM', () => server.close(() => process.exit(0)));
}
main().catch(error => { console.error(error); process.exit(1); });

