Object.assign(process.env, env, { GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null', GIT_AUTHOR_NAME: 'test', GIT_AUTHOR_EMAIL: 't@t', GIT_COMMITTER_NAME: 'test', GIT_COMMITTER_EMAIL: 't@t' });
const git = (...args) => cp.execFileSync('git', args, { cwd: dir });
git('init', '-q', '-b', 'main');
const file = path.join(dir, 'a.txt');
fs.writeFileSync(file, 'old\n'); git('add', '.'); git('commit', '-q', '-m', 'fixture');
fs.appendFileSync(file, 'new\n');
async function main() {
  const view = req('./lib/git-diff').createDiffView();
  const summary = await view.summary('a', dir);
  assert.match(summary.repos[0].files[0].patch, /\+new/);
  const stat = fs.statSync;
  let changed = false;
  fs.statSync = function(p, options) {
    const result = stat.call(this, p, options);
    if (p === file && options?.bigint && !changed) {
      changed = true;
      queueMicrotask(() => fs.appendFileSync(file, 'changed after first stat identity\n'));
    }
    return result;
  };
  try {
    assert.equal(await view.patch('a', dir, summary.snapshotId, '.', 'a.txt'), 'stale');
    assert.equal(changed, true);
  } finally { fs.statSync = stat; }
  const handlers = req('./lib/file-handlers').createFileHandlers({ resolveSessionCwd() { throw Error('unreachable lookup'); }, findSessionSource() { throw Error('unreachable source'); } });
  for (const name of ['fileContent', 'filePreview']) {
    let status, body;
    const response = { status(value) { status = value; return this; }, json(value) { body = value; return this; } };
    await handlers[name]({ query: { path: '' }, get params() { throw Error('must not read params before empty path rejection'); } }, response);
    assert.equal(status, 400); assert.deepEqual(body, { error: 'path required' });
  }
  const result = { node: process.version, proofs: ['Actual inline snapshot post-version check rejects file change after first native version stat; no deferred patch or fake Git output', 'Both prepared routes reject empty mention before request params getter or session access'] };
  fs.writeFileSync(path.join(__dirname, 'inline-result.json'), JSON.stringify(result, null, 2) + '\n');
  console.log('R4_INLINE_PROOF_PASS ' + JSON.stringify(result));
}
main().then(() => fs.rmSync(dir, { recursive: true, force: true })).catch(error => { console.error(error); fs.rmSync(dir, { recursive: true, force: true }); process.exitCode = 1; });

